#!/usr/bin/env node
/**
 * Sync canonical runner labels from runners.yaml into:
 *   - .github/actions/runner-names/action.yml (composite outputs)
 *   - .github/workflows/reusable-runner-names.yml (reusable workflow)
 *   - .github/workflows/*.{yml,yaml} (needs.runner_names.outputs.* references)
 *
 * Usage: node .github/scripts/sync-runner-names.mjs
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, '../..')
const runnersYamlPath = path.join(repoRoot, '.github/actions/runner-names/runners.yaml')
const actionPath = path.join(repoRoot, '.github/actions/runner-names/action.yml')
const reusableWorkflowPath = path.join(repoRoot, '.github/workflows/reusable-runner-names.yml')
const workflowsDir = path.join(repoRoot, '.github/workflows')

const ENV_MARKER = '# Canonical runner labels — .github/actions/runner-names/runners.yaml'
const RUNNER_NAMES_JOB = 'runner_names'
const REUSABLE_WORKFLOW = './.github/workflows/reusable-runner-names.yml'
const SKIP_WORKFLOWS = new Set(['reusable-runner-names.yml'])

function parseRunnersYaml (text) {
  const runners = {}
  for (const line of text.split('\n')) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const colon = trimmed.indexOf(':')
    if (colon === -1) continue
    const key = trimmed.slice(0, colon).trim()
    const value = trimmed.slice(colon + 1).trim()
    if (key && value) runners[key] = value
  }
  return runners
}

function envName (key) {
  return 'RN_' + key.toUpperCase()
}

function needsExpr (key) {
  return '${{ needs.' + RUNNER_NAMES_JOB + '.outputs.' + key + ' }}'
}

function describeKey (key, value) {
  const labels = {
    orch: 'Default orchestration runner',
    u22: 'GitHub-hosted Ubuntu 22.04',
    u24: 'GitHub-hosted Ubuntu 24.04',
    u22_arm: 'GitHub-hosted Ubuntu 22.04 ARM64',
    u24_arm: 'GitHub-hosted Ubuntu 24.04 ARM64',
    mac14: 'GitHub-hosted macOS 14',
    mac14_xl: 'GitHub-hosted macOS 14 xlarge',
    mac15: 'GitHub-hosted macOS 15',
    mac15_intel: 'GitHub-hosted macOS 15 Intel',
    mac15_lg: 'GitHub-hosted macOS 15 large',
    mac15_xl: 'GitHub-hosted macOS 15 xlarge',
    win22: 'GitHub-hosted Windows Server 2022',
    win25: 'GitHub-hosted Windows Server 2025',
    qvac_u22: 'Self-hosted QVAC Ubuntu 22.04 x64',
    qvac_u22_gpu: 'Self-hosted QVAC Ubuntu 22.04 x64 GPU',
    qvac_u24: 'Self-hosted QVAC Ubuntu 24.04 x64',
    qvac_u24_gpu: 'Self-hosted QVAC Ubuntu 24.04 x64 GPU',
    qvac_win25: 'Self-hosted QVAC Windows 2025 x64',
    qvac_win25_gpu: 'Self-hosted QVAC Windows 2025 x64 GPU',
    ai_linux: 'Self-hosted AI run Linux',
    ai_linux_gpu: 'Self-hosted AI run Linux GPU',
    ai_u22: 'Self-hosted AI run Ubuntu 22.04',
    ai_win11_gpu: 'Self-hosted AI run Windows 11 GPU',
    gen_win11: 'Self-hosted Windows 11 image builder',
    mini_m4: 'Self-hosted Mac mini M4',
    mini_m4_gpu: 'Self-hosted Mac mini M4 GPU'
  }
  if (key.startsWith('lbl_')) {
    return `Benchmark device label (${value})`
  }
  return labels[key] || value
}

function writeActionYml (runners) {
  const outputLines = Object.entries(runners).map(([key, value]) => {
    const desc = describeKey(key, value).replace(/"/g, '\\"')
    return `  ${key}:\n    description: "${desc}"\n    value: ${value}`
  })

  const content = `name: Runner names
description: >-
  Canonical GitHub Actions runner labels for QVAC CI. Values are defined in
  runners.yaml. Workflows resolve labels via reusable-runner-names.yml;
  steps may reference this action directly when a job already runs it.

outputs:
${outputLines.join('\n')}

runs:
  using: composite
  steps:
    - name: Runner names are static outputs
      shell: bash
      run: echo "See runners.yaml and reusable-runner-names.yml"
`

  fs.writeFileSync(actionPath, content.endsWith('\n') ? content : content + '\n')
}

function shellSingleQuote (value) {
  return "'" + value.replace(/'/g, "'\\''") + "'"
}

function writeReusableWorkflow (runners) {
  const workflowOutputs = Object.keys(runners).map((key) => {
    const desc = describeKey(key, runners[key]).replace(/"/g, '\\"')
    return `      ${key}:\n        description: ${desc}\n        value: \${{ jobs.export.outputs.${key} }}`
  }).join('\n')

  const jobOutputs = Object.keys(runners).map((key) => {
    return `      ${key}: \${{ steps.export.outputs.${key} }}`
  }).join('\n')

  const exportRunLines = Object.entries(runners).map(([key, value]) => {
    return `          echo ${key}=${shellSingleQuote(value)} >> "$GITHUB_OUTPUT"`
  }).join('\n')

  const content = `# Reusable workflow — canonical CI runner labels for caller workflows.
# Generated by .github/scripts/sync-runner-names.mjs from runners.yaml.
# Do not edit by hand; run the sync script after changing runners.yaml.

name: Runner names (reusable)

on:
  workflow_call:
    outputs:
${workflowOutputs}

permissions:
  contents: read

jobs:
  export:
    runs-on: ubuntu-latest
    outputs:
${jobOutputs}
    steps:
      - id: export
        shell: bash
        run: |
${exportRunLines}
`

  fs.writeFileSync(reusableWorkflowPath, content.endsWith('\n') ? content : content + '\n')
}

function removeExistingRunnerEnv (text) {
  let lines = text.split('\n')
  lines = removeRunnerEnvLines(lines)
  return lines.join('\n')
}

function isRunnerEnvLine (line) {
  return /^  RN_[A-Z0-9_]+:/.test(line)
}

function removeRunnerEnvLines (lines) {
  const next = lines.slice()
  while (true) {
    const markerIndex = next.findIndex((line) => line.trim() === ENV_MARKER)
    if (markerIndex === -1) break

    let end = markerIndex + 1
    while (end < next.length && isRunnerEnvLine(next[end])) {
      end += 1
    }
    next.splice(markerIndex, end - markerIndex)
  }

  for (let i = next.length - 1; i >= 0; i--) {
    if (isRunnerEnvLine(next[i])) {
      next.splice(i, 1)
    }
  }

  for (let i = next.length - 1; i >= 0; i--) {
    if (next[i] !== 'env:') continue
    const nextLine = next[i + 1]
    if (nextLine === undefined || nextLine.trim() === '' || !/^  [A-Za-z0-9_]+:/.test(nextLine)) {
      next.splice(i, 1)
    }
  }

  return next
}

function replaceRunnerReferences (text, runners) {
  let result = text

  for (const key of Object.keys(runners)) {
    const needs = needsExpr(key)
    const envWrapped = '${{ env.' + envName(key) + ' }}'
    const envBare = 'env.' + envName(key)

    result = result.split(envWrapped).join(needs)
    result = result.split(envBare).join('needs.' + RUNNER_NAMES_JOB + '.outputs.' + key)
  }

  const byValue = Object.entries(runners).sort((a, b) => b[1].length - a[1].length)
  for (const [key, value] of byValue) {
    const needs = needsExpr(key)
    result = result.replace(
      new RegExp(`^(\\s*runs-on:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${needs}`
    )
    result = result.replace(
      new RegExp(`^(\\s*runner:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${needs}`
    )
    result = result.replace(
      new RegExp(`^(\\s*runner_label:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${needs}`
    )
    result = result.replace(
      new RegExp(`^(\\s*device_label:\\s*)${escapeRegExp(value)}(\\s*)$`, 'gm'),
      `$1${needs}$2`
    )
    result = result.replace(
      new RegExp(`^(\\s*-\\s*os:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${needs}`
    )
    result = result.replace(
      new RegExp(`(\\bos:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${needs}$2`
    )
    result = result.replace(
      new RegExp(`(\\brunner:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${needs}$2`
    )
    result = result.replace(
      new RegExp(`(\\brunner_label:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${needs}$2`
    )
    result = result.replace(
      new RegExp(`(\\bdevice_label:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${needs}$2`
    )
    result = result.replace(
      new RegExp(`matrix\\.os == '${escapeRegExp(value)}'`, 'g'),
      `matrix.os == needs.${RUNNER_NAMES_JOB}.outputs.${key}`
    )
    result = result.replace(
      new RegExp(`matrix\\.os != '${escapeRegExp(value)}'`, 'g'),
      `matrix.os != needs.${RUNNER_NAMES_JOB}.outputs.${key}`
    )
    result = result.replace(
      new RegExp(`matrix\\.runner == '${escapeRegExp(value)}'`, 'g'),
      `matrix.runner == needs.${RUNNER_NAMES_JOB}.outputs.${key}`
    )
  }

  return result
}

function usesRunnerReferences (text) {
  return text.includes('needs.' + RUNNER_NAMES_JOB + '.outputs.')
}

function ensureRunnerNamesJob (lines) {
  const jobsIndex = lines.findIndex((line) => line === 'jobs:')
  if (jobsIndex === -1) return lines

  const next = lines.slice()
  let insertAt = jobsIndex + 1
  while (insertAt < next.length && (next[insertAt].trim() === '' || next[insertAt].trim().startsWith('#'))) {
    insertAt += 1
  }

  if (next[insertAt]?.trim().startsWith(`${RUNNER_NAMES_JOB}:`)) {
    return next
  }

  const block = [
    `  ${RUNNER_NAMES_JOB}:`,
    `    uses: ${REUSABLE_WORKFLOW}`,
    ''
  ]
  next.splice(insertAt, 0, ...block)
  return next
}

function parseNeedsValue (line) {
  const trimmed = line.trim()
  if (trimmed.startsWith('needs:')) {
    const value = trimmed.slice('needs:'.length).trim()
    if (value.startsWith('[')) {
      return value.slice(1, -1).split(',').map((part) => part.trim()).filter(Boolean)
    }
    return [value]
  }
  return null
}

function formatNeedsLine (indent, needs) {
  const unique = []
  for (const item of needs) {
    if (!unique.includes(item)) unique.push(item)
  }
  if (unique.length === 1) {
    return `${indent}needs: ${unique[0]}`
  }
  return `${indent}needs: [${unique.join(', ')}]`
}

function ensureJobNeedsRunnerNames (lines) {
  const next = lines.slice()
  let inJobs = false
  let jobIndent = ''
  let jobStart = -1
  let needsLineIndex = -1
  let jobUsesReusable = false
  let jobReferencesRunners = false

  function flushJob () {
    if (jobStart === -1) return
    if (!jobReferencesRunners || jobUsesReusable) {
      jobStart = -1
      needsLineIndex = -1
      jobUsesReusable = false
      jobReferencesRunners = false
      return
    }

    if (needsLineIndex === -1) {
      next.splice(jobStart, 0, `${jobIndent}  needs: ${RUNNER_NAMES_JOB}`)
    } else {
      const existing = parseNeedsValue(next[needsLineIndex]) || []
      if (!existing.includes(RUNNER_NAMES_JOB)) {
        existing.unshift(RUNNER_NAMES_JOB)
        next[needsLineIndex] = formatNeedsLine(`${jobIndent}  `, existing)
      }
    }

    jobStart = -1
    needsLineIndex = -1
    jobUsesReusable = false
    jobReferencesRunners = false
  }

  for (let i = 0; i < next.length; i++) {
    const line = next[i]
    if (line === 'jobs:') {
      inJobs = true
      continue
    }
    if (!inJobs) continue

    const jobMatch = line.match(/^  ([A-Za-z0-9_-]+):\s*$/)
    if (jobMatch) {
      flushJob()
      if (jobMatch[1] === RUNNER_NAMES_JOB) {
        jobStart = -1
        continue
      }
      jobStart = i + 1
      jobIndent = '  '
      continue
    }

    if (jobStart === -1) continue

    if (line.includes(`uses: ${REUSABLE_WORKFLOW}`)) {
      jobUsesReusable = true
    }
    if (line.includes(`needs.${RUNNER_NAMES_JOB}.outputs.`)) {
      jobReferencesRunners = true
    }

    const needs = parseNeedsValue(line)
    if (needs !== null && /^\s{4}needs:/.test(line)) {
      needsLineIndex = i
      if (needs.includes(RUNNER_NAMES_JOB)) {
        jobReferencesRunners = true
      }
    }
  }

  flushJob()
  return next
}

function readTextFile (filePath) {
  return fs.readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n')
}

function writeTextFile (filePath, text) {
  const normalized = text.replace(/\r\n/g, '\n')
  fs.writeFileSync(filePath, normalized.endsWith('\n') ? normalized : normalized + '\n')
}

function escapeRegExp (value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function patchWorkflow (filePath, runners) {
  const original = readTextFile(filePath)
  let text = removeExistingRunnerEnv(original)
  text = replaceRunnerReferences(text, runners)

  if (!usesRunnerReferences(text)) {
    if (text !== original) {
      writeTextFile(filePath, text)
      return true
    }
    return false
  }

  let lines = text.split('\n')
  lines = ensureRunnerNamesJob(lines)
  lines = ensureJobNeedsRunnerNames(lines)
  text = lines.join('\n')

  if (text !== original) {
    writeTextFile(filePath, text)
    return true
  }
  return false
}

function main () {
  const runnersYaml = fs.readFileSync(runnersYamlPath, 'utf8')
  const runners = parseRunnersYaml(runnersYaml)
  if (Object.keys(runners).length === 0) {
    throw new Error(`No runners parsed from ${runnersYamlPath}`)
  }

  writeActionYml(runners)
  writeReusableWorkflow(runners)

  const workflowFiles = fs.readdirSync(workflowsDir)
    .filter((name) => (name.endsWith('.yml') || name.endsWith('.yaml')) && !SKIP_WORKFLOWS.has(name))
    .map((name) => path.join(workflowsDir, name))

  let patched = 0
  for (const file of workflowFiles) {
    if (patchWorkflow(file, runners)) patched += 1
  }

  console.log(`Synced ${Object.keys(runners).length} runner labels`)
  console.log(`Updated action: ${path.relative(repoRoot, actionPath)}`)
  console.log(`Updated reusable workflow: ${path.relative(repoRoot, reusableWorkflowPath)}`)
  console.log(`Patched ${patched}/${workflowFiles.length} workflow files`)
}

main()
